import math

PHI = (1 + math.sqrt(5)) / 2


def solve(text: str) -> str:
    a, b = map(int, text.split()[:2])
    if is_cold(a, b):
        return 'LOSE'
    for i in range(a + 1):
        for j in range(b + 1):
            if i == 0 and j == 0:
                continue
            if is_cold(a - i, b - j):
                return 'WIN %d %d' % (i, j)
    return 'LOSE'


def is_cold(x, y):
    if x > y:
        x, y = y, x
    if x == 0:
        return y == 0
    n = y - x
    return int(n * PHI) == x and int(n * PHI * PHI) == y
